import java.util.*;

class Solution {
    public int rob(int[] coins) {
        int skip = 0, take = 0;              // best totals up to i-2 and i-1
        for (int v : coins) {
            int cur = Math.max(take, skip + v); // skip this pile, or take it and skip the neighbour
            skip = take;
            take = cur;
        }
        return take;
    }
}

